import{_ as a,o as t,c as i,a4 as o}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"R: RAM Disk 折腾记录","description":"","frontmatter":{"title":"R: RAM Disk 折腾记录","date":"2026-07-12T00:00:00.000Z"},"headers":[],"relativePath":"posts/ramdisk-troubleshooting.md","filePath":"posts/ramdisk-troubleshooting.md"}'),d={name:"posts/ramdisk-troubleshooting.md"};function s(r,e,l,n,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="r-ram-disk-折腾记录" tabindex="-1">R: RAM Disk 折腾记录 <a class="header-anchor" href="#r-ram-disk-折腾记录" aria-label="Permalink to &quot;R: RAM Disk 折腾记录&quot;">​</a></h1><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h2><ul><li>C: SSD — 系统盘（目标：减少写入）</li><li>R: — 1GB ImDisk RAM 盘（type vm，无镜像文件）</li><li>系统 zh-CN，原 ACP=65001（UTF-8 Beta）→ 改回 936</li></ul><hr><h2 id="一、r-初始化问题" tabindex="-1">一、R: 初始化问题 <a class="header-anchor" href="#一、r-初始化问题" aria-label="Permalink to &quot;一、R: 初始化问题&quot;">​</a></h2><h3 id="症状" tabindex="-1">症状 <a class="header-anchor" href="#症状" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p>开机后 R: 盘符存在但为 RAW，启动脚本 mkdir 静默失败。</p><h3 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h3><p>ImDisk 持久注册表配置只建了设备（Type=0x1 VM），没有文件系统。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>HKLM\\SYSTEM\\CurrentControlSet\\Services\\ImDisk\\Parameters\\Disk0</span></span>
<span class="line"><span>  Size       = 0x40000000  (1GB)</span></span>
<span class="line"><span>  MountPoint = \\??\\R:</span></span>
<span class="line"><span>  Type       = 0x1         (VM, no image file)</span></span></code></pre></div><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><p>启动脚本 <code>init_r_drive.bat</code> 加入 RAW 检测 + 自动格式化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>fsutil fsinfo volumeinfo R:\\ | find /i &quot;NTFS&quot;</span></span>
<span class="line"><span>if errorlevel 1 (</span></span>
<span class="line"><span>    format R: /q /y /fs:ntfs /v:RAMDISK</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>脚本路径：<code>%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\init_r_drive.bat</code></p><h3 id="当前脚本行为" tabindex="-1">当前脚本行为 <a class="header-anchor" href="#当前脚本行为" aria-label="Permalink to &quot;当前脚本行为&quot;">​</a></h3><ol><li>循环等待 R: 就绪（最长 30 秒）</li><li>检测文件系统，RAW 则 Quick Format 为 NTFS</li><li>创建全部所需目录（幂等，mkdir 2&gt;nul）</li></ol><hr><h2 id="二、temp-重定向与-opencode-冲突" tabindex="-1">二、TEMP 重定向与 opencode 冲突 <a class="header-anchor" href="#二、temp-重定向与-opencode-冲突" aria-label="Permalink to &quot;二、TEMP 重定向与 opencode 冲突&quot;">​</a></h2><h3 id="症状-1" tabindex="-1">症状 <a class="header-anchor" href="#症状-1" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p><code>%TEMP%</code> 设为 <code>R:\\temp</code> 后，<code>opencode -c</code>（启动 TUI）报错：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Failed to initialize OpenTUI render library:</span></span>
<span class="line"><span>Failed to open library &quot;B:/~BUN/root/opentui-2nr24hkx.dll&quot;: error code 126</span></span></code></pre></div><p>CLI 命令（<code>--version</code>、<code>--list-files</code>）正常。</p><h3 id="原因-1" tabindex="-1">原因 <a class="header-anchor" href="#原因-1" aria-label="Permalink to &quot;原因&quot;">​</a></h3><p>opencode.exe 是 Bun 打包的独立二进制（184MB）。Bun 在启动时将内置的 opentui.dll 提取到 <code>%TEMP%</code> 下并加载。当 TEMP=R: 时：</p><ul><li><code>GetTempPath</code> 返回正确 (<code>R:\\temp\\</code>)</li><li>文件读写正常</li><li><code>LoadLibrary</code> 从 R: 加载原生 DLL 正常</li><li>但 <strong>Bun 不在 R: 上创建任何临时文件</strong>（FileSystemWatcher 零事件）</li></ul><p>结论：<strong>Bun 独立二进制与 ImDisk RAM 盘存在兼容性问题</strong>，提取原生插件阶段静默跳过。</p><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><p><code>%TEMP%</code> 改回系统默认 <code>%USERPROFILE%\\AppData\\Local\\Temp</code>。</p><h3 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h3><ul><li>如果不使用 opencode TUI（只用 CLI），<code>%TEMP%</code> 可以指向 R:</li><li>其他程序（Chrome、Edge、Clash Verge）不受影响</li></ul><hr><h2 id="三、clash-verge-clash-verge-rev-日志目录" tabindex="-1">三、Clash Verge（clash-verge-rev）日志目录 <a class="header-anchor" href="#三、clash-verge-clash-verge-rev-日志目录" aria-label="Permalink to &quot;三、Clash Verge（clash-verge-rev）日志目录&quot;">​</a></h2><h3 id="症状-2" tabindex="-1">症状 <a class="header-anchor" href="#症状-2" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p>启动崩溃：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Failed to setup app: error encountered during setup hook:</span></span>
<span class="line"><span>Log cannot be written, e.g. because the configured output directory is not accessible</span></span></code></pre></div><h3 id="原因-2" tabindex="-1">原因 <a class="header-anchor" href="#原因-2" aria-label="Permalink to &quot;原因&quot;">​</a></h3><p><code>%APPDATA%\\io.github.clash-verge-rev.clash-verge-rev\\logs</code> 被错误设为 symlink 指向 <code>R:\\logs\\clash</code>，但 R: 上该目录不存在。Tauri 2 初始化时写日志失败导致 panic。</p><h3 id="修复-2" tabindex="-1">修复 <a class="header-anchor" href="#修复-2" aria-label="Permalink to &quot;修复&quot;">​</a></h3><p>删除该 symlink，重建为普通目录。</p><hr><h2 id="四、图吧工具箱乱码" tabindex="-1">四、图吧工具箱乱码 <a class="header-anchor" href="#四、图吧工具箱乱码" aria-label="Permalink to &quot;四、图吧工具箱乱码&quot;">​</a></h2><h3 id="症状-3" tabindex="-1">症状 <a class="header-anchor" href="#症状-3" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p>界面文字全部乱码。</p><h3 id="原因-3" tabindex="-1">原因 <a class="header-anchor" href="#原因-3" aria-label="Permalink to &quot;原因&quot;">​</a></h3><p>系统 ANSI Code Page (ACP) 被设为 65001（UTF-8 Beta 功能）。旧程序调用 ANSI API 时收到 UTF-8 而非预期的 GBK (CP936)，导致中文乱码。</p><h3 id="修复-3" tabindex="-1">修复 <a class="header-anchor" href="#修复-3" aria-label="Permalink to &quot;修复&quot;">​</a></h3><p>ACP 从 65001 改回 936：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>reg add &quot;HKLM\\SYSTEM\\CurrentControlSet\\Control\\Nls\\CodePage&quot; /v ACP /t REG_DWORD /d 936 /f</span></span></code></pre></div><p>需重启生效。</p><h3 id="微调替代方案" tabindex="-1">微调替代方案 <a class="header-anchor" href="#微调替代方案" aria-label="Permalink to &quot;微调替代方案&quot;">​</a></h3><p>用 Locale Emulator (github.com/xupefei/Locale-Emulator) 单独指定程序运行的语言环境，不更改系统全局 ACP。</p><hr><h2 id="五、浏览器缓存重定向-当前生效" tabindex="-1">五、浏览器缓存重定向（当前生效） <a class="header-anchor" href="#五、浏览器缓存重定向-当前生效" aria-label="Permalink to &quot;五、浏览器缓存重定向（当前生效）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缓存</th><th>C: 原路径</th><th>R: 目标</th></tr></thead><tbody><tr><td>Chrome Cache</td><td><code>%LOCALAPPDATA%\\Google\\Chrome\\User Data\\Default\\Cache</code></td><td><code>R:\\chrome-cache</code></td></tr><tr><td>Chrome Code Cache</td><td><code>%LOCALAPPDATA%\\Google\\Chrome\\User Data\\Default\\Code Cache</code></td><td><code>R:\\chrome-code-cache</code></td></tr><tr><td>Edge Cache</td><td><code>%LOCALAPPDATA%\\Microsoft\\Edge\\User Data\\Default\\Cache</code></td><td><code>R:\\edge-cache</code></td></tr><tr><td>Edge Code Cache</td><td><code>%LOCALAPPDATA%\\Microsoft\\Edge\\User Data\\Default\\Code Cache</code></td><td><code>R:\\edge-code-cache</code></td></tr><tr><td>ccswitch Cache</td><td><code>%LOCALAPPDATA%\\com.ccswitch.desktop\\Cache</code></td><td><code>R:\\com.ccswitch.desktop\\Cache</code></td></tr></tbody></table><p>均为 Junction 类型（<code>mklink /j</code>），需管理员权限创建。</p><hr><h2 id="六、其他已撤销的系统改动" tabindex="-1">六、其他已撤销的系统改动 <a class="header-anchor" href="#六、其他已撤销的系统改动" aria-label="Permalink to &quot;六、其他已撤销的系统改动&quot;">​</a></h2><p>以下为尝试过的 SSD 写入优化，因兼容性问题已撤销或保留但非必需：</p><table tabindex="0"><thead><tr><th>改动</th><th>状态</th><th>原因</th></tr></thead><tbody><tr><td>禁用 EventLog</td><td>已撤销</td><td>部分程序依赖</td></tr><tr><td>WMI ETL 日志 (DENY ACL)</td><td>保留</td><td>不影响日常使用</td></tr><tr><td>waasmedic 日志 (DENY ACL)</td><td>保留</td><td>不影响日常使用</td></tr><tr><td>禁用 WaaSMedicSvc</td><td>保留</td><td>注册表 Start=4</td></tr><tr><td>禁用 Clipboard 服务</td><td>已撤销</td><td>影响剪贴板功能</td></tr><tr><td>RDP AutoTrace</td><td>已撤销</td><td>非必要</td></tr><tr><td>用户 TEMP→R:\\temp</td><td>已撤销</td><td>导致 opencode TUI 崩溃</td></tr><tr><td>C:\\Windows\\Temp junction</td><td>已撤销</td><td>导致系统组件异常</td></tr></tbody></table><hr><h2 id="七、经验总结" tabindex="-1">七、经验总结 <a class="header-anchor" href="#七、经验总结" aria-label="Permalink to &quot;七、经验总结&quot;">​</a></h2><ol><li><strong>RAM 盘（ImDisk VM 型）与 Bun 独立二进制不兼容</strong> — Bun 提取原生 DLL 时静默跳过 RAM 盘，原因未明。<code>LoadLibrary</code> 本身从 R: 加载 DLL 没问题。</li><li><strong>ACP=65001（UTF-8 Beta）坑老程序</strong> — 旧版 Windows 程序用 ANSI API 的必炸，不改回来无解。</li><li><strong>Symlink 依赖初始化</strong> — R: 是易失的，symlink 指向 R: 的程序必须在 R: 建好目录后才能启动。</li><li><strong>先验证单项再推下一个</strong> — 这次一次性上了 17 项改动，出问题根本定位不了。</li><li><strong>启动脚本要幂等</strong> — <code>mkdir 2&gt;nul</code>、循环等待、RAW 格式化，每次开机都能安全重跑。</li></ol>`,62)])])}const b=a(d,[["render",s]]);export{u as __pageData,b as default};
